// «Мозг» голосового ассистента Bowhard: ответ по базе знаний без внешних сервисов.
//
// Живёт в узле Code процесса n8n «Голосовой ассистент: ответ по базе знаний».
// Почему Code, а не выражение: здесь проверка входа (токен, пустой текст, длина), скоринг реплики
// по таблице тем, склейка двух тем в одном ответе и подсказка после повторного непонимания —
// это многошаговый алгоритм, выражением не читается.
//
// В файле стоит заглушка токена: настоящее значение подставляется при записи в n8n
// (хранится в DPAPI-хранилище как voice-brain-token). В репозиторий токен не попадает.
//
// Вход (от VoxEngine): { body: { text, callId, fallbacks }, headers: { 'x-brain-token' } }
//   fallbacks — сколько раз подряд ассистент не понял клиента (сценарий считает сам).
// Выход: { valid, httpStatus, errorCode, errorMessage, intent, answer, score, contact, heard }
//
// ПРАВИЛА ТЕКСТА ОТВЕТОВ (проверены живым синтезом и распознаванием 06.10.2026):
//   • цифр в ответах нет — только словами («от пятнадцати тысяч рублей»): синтез читает их верно;
//   • «ИИ» писать нельзя: синтез читает как «и» («ИИ-ассистент» → «и ассистент») — только
//     «искусственный интеллект» или «ассистент»;
//   • «1С» — только «один-эс»; латинское «CRM» читается как «си эр эм» — это допустимо;
//   • адреса сайтов и почту не диктуем (звучит как «боуэрт точка ру») — просим телефон;
//   • ответ — не длиннее ~250 знаков: это примерно 15 секунд речи. Живой звонок 06.10.2026
//     показал, что 400 знаков (26 секунд) клиент слушать не готов — он положил трубку.

const incoming = $input.first().json || {};
const body = incoming.body || {};
const headers = incoming.headers || {};
const TOKEN = 'REPLACE_WITH_YOUR_TOKEN';

const text = String(body.text || '').trim();
const token = String(headers['x-brain-token'] || body.token || '').trim();
const fallbacks = Number(body.fallbacks || 0);

function bad(httpStatus, errorCode, errorMessage) {
  return [{ json: { valid: false, httpStatus: httpStatus, errorCode: errorCode, errorMessage: errorMessage, intent: '', answer: '', score: 0, contact: '' } }];
}

if (token !== TOKEN) return bad(401, 'unauthorized', 'Неверный токен запроса');
if (!text) return bad(400, 'validation_error', 'Нужно непустое поле text');
if (text.length > 500) return bad(400, 'validation_error', 'Слишком длинный текст (лимит 500 символов)');

const normalized = text.toLowerCase().replace(/ё/g, 'е').replace(/[^a-zа-я0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

// Клиент продиктовал номер телефона — самый полезный исход разговора: подтверждаем и завершаем.
// Номер целиком попадёт в заявку CRM вместе с расшифровкой разговора.
const digitCount = (text.match(/[0-9]/g) || []).length;
if (digitCount >= 10) {
  let contact = text.replace(/[^0-9]/g, '');
  if (contact.length === 11 && contact.charAt(0) === '8') contact = '7' + contact.slice(1);
  if (contact.length === 10) contact = '7' + contact;
  if (contact.length > 20) contact = contact.slice(0, 20);
  return [{
    json: {
      valid: true,
      httpStatus: 200,
      errorCode: '',
      errorMessage: '',
      intent: 'phone_given',
      answer: 'Записал номер, спасибо! Передаю заявку — Александр перезвонит в рабочее время и ответит на все вопросы. До свидания!',
      score: digitCount,
      contact: contact,
      heard: normalized
    }
  }];
}

// База знаний студии Bowhard. Ключевые слова — как их слышит распознавание (без пунктуации):
